import {DIMENSIONS,ALL_DIMENSIONS,KINDS,isComparable,garmentCandidates,bodyCandidates,summarizeDifferences,displayName,fitLevel,isStretchy,summarizeByBrand,lengthClass,lengthLabel,typicalSizes,typicalReference} from './mobile-engine.js';
import {SEASONS,FABRICS,fabricProfile,keywordBadge} from './traits.js';
import {renderCatalog,renderCatalogCards} from './catalog.js';

document.body.classList.add('mobile-design');
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" class="ico" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 3v18m4-12h4m-4 4h4"/>',save:'<path d="M6 3h12v18l-6-4-6 4z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',ruler:'<path d="m3 15 12-12 6 6L9 21zM12 6l3 3m-6 0 2 2m-5 1 3 3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 4H4v16h16v-6"/>',hanger:'<path d="M9 6a3 3 0 1 1 5 2c-1 1-2 1-2 3l9 6v3H3v-3l9-6"/>'})[name]??''}</svg>`;
const sparkle=(cx,cy,r,fill)=>'<polygon fill="'+fill+'" points="'+Array.from({length:16},(_,i)=>{const a=Math.PI*i/8,d=i%2?r*.42:r;return (cx+Math.sin(a)*d).toFixed(1)+','+(cy-Math.cos(a)*d).toFixed(1);}).join(' ')+'"/>';
function clothes(color='#f1c8d7',pattern='dots',suffix='a',bottom=color){
 const top='M87 24 62 33 25 69 45 91 70 75v78h110V75l25 16 20-22-37-36-25-9c-4 20-21 28-38 28S91 44 87 24Z',pants='M73 174h109l-6 104h-43l-6-67-9 67H72z';
 const sticker='stroke="#fffdf7" stroke-width="9" stroke-linejoin="round" paint-order="stroke"',line='stroke="#4a3528" stroke-opacity=".38" stroke-width="1.6" stroke-linecap="round" fill="none"';
 return `<svg class="clothes-art" viewBox="0 0 250 290" fill="none" aria-hidden="true"><g transform="rotate(-7 120 80)"><path d="${top}" fill="${color}" ${sticker}/><path d="M87 26q8 26 38 26t38-26M71 142h108M33 62l19 21m145 0 19-21" ${line}/>${sparkle(98,100,11,'#f3eede')}${sparkle(152,84,7,'#fffdf7')}${sparkle(146,124,9,'#f3eede')}<g fill="#fffdf7"><circle cx="122" cy="74" r="2.2"/><circle cx="84" cy="128" r="2.2"/><circle cx="166" cy="104" r="2.2"/><circle cx="118" cy="128" r="2.2"/><circle cx="50" cy="70" r="2"/><circle cx="201" cy="68" r="2"/></g></g><g transform="rotate(7 135 222)"><path d="${pants}" fill="${bottom}" ${sticker}/><path d="M74 184h106m-53 2v25" ${line}/><path d="m122 185-8 11m8-11 9 10" stroke="#fffdf7" stroke-width="2.6" stroke-linecap="round"/>${sparkle(98,232,8,'#fffdf7')}<g fill="#fffdf7"><circle cx="152" cy="208" r="2.2"/><circle cx="160" cy="246" r="2.2"/><circle cx="92" cy="204" r="2.2"/><circle cx="104" cy="262" r="2.2"/><circle cx="146" cy="268" r="2"/></g></g></svg>`;
}
const wordmark=()=>`<img class="wordmark" src="./assets/mobile/logo.png" alt="KKOKMAT" width="250" height="59">`;
let data;
const bodyInputValues=()=>({height:state.height===''?null:Number(state.height),weight:state.weight===''?null:Number(state.weight)});
function bodyInputs(required=false){return `<div class="body-inputs"><label>최근에 잰 키${required?'':' <small>선택</small>'}<div class="unit-input"><input name="height" type="number" inputmode="decimal" min="40" max="140" step="0.1" ${required?'required':''} placeholder="예: 102" value="${esc(state.height)}"><span>cm</span></div></label><label>체중${required?'':' <small>선택</small>'}<div class="unit-input"><input name="weight" type="number" inputmode="decimal" min="2" max="40" step="0.1" ${required?'required':''} placeholder="예: 16" value="${esc(state.weight)}"><span>kg</span></div></label></div><p class="field-help">${required?'키와 체중을 모두 입력해 주세요. 체중을 모르면 입던 옷의 실측으로 비교해 주세요.':'키·체중을 각각 확인해요. 체중 미입력·공식 자료 미공개는 미검증으로 표시해요.'}</p>`;}
function observedClothingFields(){return `<div class="observed-clothing"><h3>지금 편안하게 맞는 옷이 있나요? <small>선택</small></h3><p class="field-help">입던 사이즈와 신체 기준표가 다르면 실측을 먼저 확인해요.</p><label class="field-label" for="wearing-brand">현재 잘 맞는 옷의 브랜드</label><select id="wearing-brand" name="wearingBrand"><option value="">모르겠어요 / 선택 안 함</option>${data.brands.map(b=>`<option value="${b.id}" ${state.wearingBrand===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><label class="field-label" for="wearing-size">현재 잘 맞는 옷의 사이즈</label><input class="wearing-size-input" id="wearing-size" name="wearingSize" maxlength="16" placeholder="예: 110" value="${esc(state.wearingSize??'')}"></div>`;}
const state={view:'compare',step:1,mode:'garment',referenceBrand:'',referenceProduct:'',referenceSize:'',manual:false,manualValues:{},fit:'well',differentFabric:false,referenceFabric:'',season:'any',height:'',weight:'',wearingBrand:'',wearingSize:'',resultLimit:12,targetBrand:'all',targetProduct:'all',results:null,reference:null,dbSearch:'',dbFilter:'all',dbKind:'all',dbStatus:'all',dbPage:1,referenceKind:'homewear-set',referenceSearch:'',referenceTypical:false,bodyPriority:{}};
let saved=[];try{saved=JSON.parse(localStorage.getItem('kokmat-comparisons')||'[]');if(!Array.isArray(saved))saved=[];}catch{}
const brand=id=>data.brands.find(b=>b.id===id);
const product=id=>data.products.find(p=>p.id===id);
const productCount=id=>data.products.filter(p=>p.brandId===id).length;
function productArt(p,suffix){
 const b=brand(p.brandId);
 const imageUrl=data.catalog.find(item=>item.measurementId===p.id&&/^https?:\/\//i.test(item.imageUrl??''))?.imageUrl;
 return `<div class="product-art" style="background:${b.color}"><div class="product-art-fallback"${imageUrl?' aria-hidden="true"':''}>${clothes(b.ink,'dots',suffix)}<span>이미지 없음</span></div>${imageUrl?`<img src="${esc(imageUrl)}" alt="${esc(b.name+' '+displayName(p.name))} 상품 이미지" width="188" height="220" loading="lazy" decoding="async" referrerpolicy="no-referrer" onload="this.previousElementSibling.hidden=true" onerror="this.hidden=true;this.previousElementSibling.removeAttribute('aria-hidden')">`:''}</div>`;
}
const options=(items,value,label='선택해 주세요')=>`<option value="">${label}</option>`+items.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('');
const fmt=n=>Number.isInteger(n)?String(n):String(Math.round(n*100)/100);
const fitMessage=()=>state.fit==='small'?'주요 치수가 조금 더 큰 옷을 추천해요.':state.fit==='large'?'주요 치수가 조금 더 작은 옷을 추천해요.':'입던 옷과 치수가 가장 가까운 사이즈를 찾아요.';
const fabricLabel=p=>fabricProfile(p).fibers.map(f=>FABRICS[f]??f).join('·');
function preferenceFields(){
 const p=state.manual?null:product(state.referenceProduct),known=fabricProfile(p).fibers.length;
 return `<div class="fit-response" aria-live="polite">${icon('spark',15)}<span>${fitMessage()}</span></div><div class="preference-fields"><label class="fabric-option"><input type="checkbox" name="differentFabric" ${state.differentFabric?'checked':''}><span><strong>기준 옷과 다른 원단 추천 받을래요</strong><small>선택사항</small></span></label>${state.differentFabric?known?`<p class="field-help preference-help">기준 원단: ${esc(fabricLabel(p))} · 주요 소재나 원단 조직이 다른 옷을 찾아요.</p>`:`<label class="field-label" for="reference-fabric">기준 옷의 원단</label><select id="reference-fabric" name="referenceFabric" required>${options(Object.entries(FABRICS),state.referenceFabric,'원단을 선택해 주세요')}</select><p class="field-help preference-help">옷 라벨에서 주요 원단을 확인해 주세요.</p>`:''}<fieldset class="season-field"><legend>언제 입힐 옷인가요? <small>선택사항</small></legend><div class="season-options">${Object.entries(SEASONS).map(([value,label])=>`<label class="season-option ${state.season===value?'selected':''}"><input type="radio" name="season" value="${value}" ${state.season===value?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset></div>`;
}
function preferenceSummary(){return `<div class="preference-summary"><span>${state.fit==='small'?'조금 더 크게':state.fit==='large'?'조금 더 작게':'가까운 사이즈'}</span>${state.step===3&&state.mode==='garment'&&state.reference&&lengthLabel(lengthClass(state.reference,state.referenceKind,state.manual?'':product(state.referenceProduct)?.name??''))?`<span>${lengthLabel(lengthClass(state.reference,state.referenceKind,state.manual?'':product(state.referenceProduct)?.name??''))}끼리</span>`:''}${state.differentFabric?'<span>다른 원단</span>':''}${state.season!=='any'?`<span>${SEASONS[state.season]}</span>`:''}</div>`;}
function header(){return `<header class="site-header"><div class="header-inner"><button class="logo" data-action="home" aria-label="꼭맞 처음으로">${wordmark()}<span class="logo-tag">little fit, big comfort</span></button><nav class="desktop-nav" aria-label="주요 메뉴">${navButtons()}</nav><button class="text-link header-source" data-action="method">공식 데이터로 비교해요 ${icon('info',16)}</button></div></header>`;}
function navButtons(){return [['compare','사이즈 비교','ruler'],['database','브랜드 가이드','book'],['saved','저장한 비교','save']].map(([v,l,i])=>`<button data-action="view" data-view="${v}" class="nav-item ${state.view===v?'active':''}" ${state.view===v?'aria-current="page"':''}>${icon(i,18)}<span>${l}</span>${v==='saved'&&saved.length?`<small>${saved.length}</small>`:''}</button>`).join('');}
function footer(){return `<footer class="site-footer"><span class="footer-logo">${wordmark()}</span><p>아이의 오늘에, 편안하게 맞도록.</p><div><button data-action="method">비교 기준</button><button data-action="sources">데이터 출처</button><a href="./data.json" download="kokmat-size-database.json">데이터 다운로드</a></div><small>브랜드와 제휴하지 않은 독립 비교 서비스 · 공식표 확인 ${data.checkedAt.replaceAll('-','.')}<br>상품의 판매 여부·재고·가격은 연동하지 않습니다.</small></footer><nav class="mobile-nav" aria-label="모바일 주요 메뉴">${navButtons()}</nav>`;}
function hero(){return `<section class="hero mobile-hero"><div class="hero-copy"><img class="mobile-hero-patch" src="./assets/mobile/hero-patch.png" alt="" width="214" height="120" fetchpriority="high"><h1><span class="mobile-handwriting">잘 맞던 그 옷이,</span><span class="mobile-headline">새 옷의 기준이 되도록</span></h1><p>브랜드가 달라도 괜찮아요.<br>입던 옷과 나란히 비교하고, 다음 사이즈를 찾아보세요.</p><div class="hero-meta"><span>${icon('check',14)} ${data.brands.length}개 브랜드</span><span>${icon('check',14)} 공식 실측·신체 가이드</span></div></div></section>`;}
function stepper(){return `<div class="stepper" aria-label="진행 단계">${['기준 정보','비교할 옷','비교 결과'].map((l,i)=>`<div class="step ${state.step===i+1?'current':''} ${state.step>i+1?'done':''}"><span>${state.step>i+1?icon('check',12):'0'+(i+1)}</span>${l}</div>`).join('<i class="step-line"></i>')}</div>`;}
const searchKey=s=>String(s??'').replace(/\s+/g,'').toLowerCase();
// 옷 라벨에 적히는 품번만 보여준다. 쇼핑몰 내부 상품번호(숫자만)는 라벨에 없으므로 숨긴다.
const labelCode=p=>p.name.match(/\(([0-9A-Z]{5}-[0-9]{3}-[0-9A-Z]{2})\)/)?.[1]??(/[A-Z]/.test(p.code)&&p.code.length>=8?p.code:'');
let thumbs;
const thumbOf=id=>{thumbs??=new Map(data.catalog.filter(item=>item.measurementId&&/^https?:\/\//i.test(item.imageUrl??'')).map(item=>[item.measurementId,item.imageUrl]));return thumbs.get(id);};
// 입던 옷 찾기: 상품명을 몰라도 사진과 라벨의 품번으로 고를 수 있게 한다.
function pickList(products){
 const terms=String(state.referenceSearch??'').trim().split(/\s+/).filter(Boolean).map(searchKey),found=products.filter(p=>!terms.length||terms.every(t=>searchKey(p.name+' '+p.code).includes(t))),shown=found.slice(0,12);
 if(state.referenceProduct&&!shown.some(p=>p.id===state.referenceProduct)){const picked=products.find(p=>p.id===state.referenceProduct);if(picked)shown.unshift(picked);}
 return `<p class="field-help pick-count">${found.length?`${found.length}개 중 ${Math.min(found.length,12)}개 표시${found.length>12?' · 검색해서 좁혀 보세요':''}`:'검색 결과가 없어요. 다른 낱말이나 품번 일부로 찾아보세요.'}</p><div class="pick-list">${shown.map(p=>{const img=thumbOf(p.id),b=brand(p.brandId);return `<button type="button" class="pick-item ${p.id===state.referenceProduct?'selected':''}" data-action="pick-product" data-product="${esc(p.id)}" aria-pressed="${p.id===state.referenceProduct}"><span class="pick-thumb" style="background:${b.color}">${img?`<img src="${esc(img)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true">`:''}</span><span class="pick-text"><strong>${esc(displayName(p.name))}</strong><small>${labelCode(p)?'품번 '+esc(labelCode(p))+' · ':''}${p.sizes.map(s=>esc(s.label)).join(' ')}</small></span></button>`;}).join('')}</div>`;
}
function referencePicker(b,products,p){
 const sizeSelect=(items,placeholder,disabled)=>`<label class="field-label" for="reference-size">옷 라벨에 적힌 사이즈</label><select id="reference-size" name="referenceSize" ${disabled?'disabled':''} required>${options(items,state.referenceSize,placeholder)}</select>`;
 if(state.referenceTypical){
  const sizes=typicalSizes(data,state.referenceBrand,state.referenceKind),info=state.referenceSize?typicalReference(data,{brand:state.referenceBrand,kind:state.referenceKind,size:state.referenceSize}):null;
  return `<div class="notice neutral">${icon('info',18)}<span>어떤 상품인지 몰라도 괜찮아요. <strong>${esc(b.name)} ${esc(KINDS[state.referenceKind].label)}</strong>의 같은 사이즈 상품들에서 <strong>중간 치수</strong>를 뽑아 기준으로 써요. 상품마다 핏이 달라 실제 입던 옷과 차이가 날 수 있어요.</span></div>${sizeSelect(sizes.map(s=>[s.label,s.label+' · '+s.count+'개 상품']),'사이즈를 선택해 주세요',false)}${info?`<p class="field-help">${info.count}개 상품의 중간값 · ${Object.entries(info.values).filter(([k])=>DIMENSIONS[k]).map(([k,v])=>DIMENSIONS[k]+' '+fmt(v)).join(' · ')}</p>`:''}<button type="button" class="inline-link missing-link" data-action="typical" data-on="false">상품을 알고 있어요 · 사진으로 고르기 ${icon('arrow',14)}</button>`;
 }
 return `<label class="field-label" for="reference-search">입고 있는 상품</label><label class="search-box pick-search"><span>⌕</span><input type="search" id="reference-search" placeholder="상품명 또는 옷 라벨의 품번" value="${esc(state.referenceSearch??'')}" autocomplete="off" aria-label="상품명이나 품번으로 찾기"></label><div id="reference-results">${pickList(products)}</div>${sizeSelect(p?.sizes.filter(s=>KINDS[p.kind].required.every(k=>Number.isFinite(s[k]))).map(s=>[s.label,s.label])??[],p?'사이즈를 선택해 주세요':'상품을 먼저 골라 주세요',!p)}<button type="button" class="inline-link missing-link" data-action="typical" data-on="true">어떤 상품인지 모르겠어요 · 브랜드와 사이즈만으로 비교 ${icon('arrow',14)}</button>`;
}
function firstStep(){
 const b=brand(state.referenceBrand),products=data.products.filter(p=>p.brandId===state.referenceBrand&&p.kind===state.referenceKind&&isComparable(p)),p=product(state.referenceProduct);
 return `<div class="form-heading"><span class="section-number">01</span><div><h2>무엇을 기준으로 비교할까요?</h2><p>잘 맞는 옷이 있다면 더 구체적으로 비교할 수 있어요.</p></div></div><div class="segmented" role="group" aria-label="비교 방법"><button data-action="mode" data-mode="garment" aria-pressed="${state.mode==='garment'}" class="${state.mode==='garment'?'selected':''}">${icon('hanger',18)} 입던 옷으로</button><button data-action="mode" data-mode="body" aria-pressed="${state.mode==='body'}" class="${state.mode==='body'?'selected':''}">${icon('ruler',18)} 아이 키·체중으로</button></div>
 <form id="reference-form">${state.mode==='garment'?`
 <label class="field-label" for="reference-kind">비교할 상품 종류</label><select id="reference-kind" name="referenceKind">${Object.entries(KINDS).filter(([,v])=>v.required.length).map(([k,v])=>`<option value="${k}" ${state.referenceKind===k?'selected':''}>${v.label}</option>`).join('')}</select><div class="inline-tabs"><button type="button" data-action="manual" data-manual="false" class="${!state.manual?'active':''}">상품 찾기</button><button type="button" data-action="manual" data-manual="true" class="${state.manual?'active':''}">직접 잰 치수 입력</button></div>
 ${state.manual?`<div class="notice neutral">${icon('ruler',18)}<span>옷을 평평하게 놓고 재주세요. 가슴은 둘레가 아닌 <strong>가로 단면</strong>이에요.</span></div><div class="measurement-inputs">${KINDS[state.referenceKind].fields.map(k=>[k,ALL_DIMENSIONS[k]]).map(([k,l])=>`<label>${l}${!KINDS[state.referenceKind].required.includes(k)?'<small>선택</small>':''}<div class="unit-input"><input name="manual-${k}" type="number" inputmode="decimal" min="5" max="120" step="0.1" value="${esc(state.manualValues[k]??'')}" ${KINDS[state.referenceKind].required.includes(k)?'required':''} placeholder="0" aria-label="${l}"><span>cm</span></div></label>`).join('')}</div>`:`
 <label class="field-label" for="reference-brand">입고 있는 브랜드</label><select id="reference-brand" name="referenceBrand" required>${options(data.brands.map(b=>[b.id,b.name+' · '+data.products.filter(p=>p.brandId===b.id&&p.kind===state.referenceKind&&isComparable(p)).length+'개 실측']),state.referenceBrand,'브랜드를 선택해 주세요')}</select>
 ${b&&!products.length?`<div class="notice amber">${icon('info',18)}<span>${esc(b.name)}의 이 종류는 비교할 실측을 확보하지 못했어요. 옷의 실측을 직접 입력하거나 <button type="button" class="inline-link" data-action="mode" data-mode="body">키·체중으로 비교</button>해 주세요.</span></div>`:`${referencePicker(b,products,p)}`}
 <button type="button" class="inline-link missing-link" data-action="manual" data-manual="true">찾는 브랜드나 상품이 없나요? ${icon('arrow',14)}</button>`}
 <fieldset class="fit-field"><legend>그 옷이 지금 어떻게 맞나요?</legend><div class="fit-options">${[['well','편안하게 맞아요',''],['small','조금 작아졌어요','↔'],['large','여유가 많아요','⌁']].map(([v,l,s])=>`<label class="fit-option ${state.fit===v?'selected':''}"><input type="radio" name="fit" value="${v}" ${state.fit===v?'checked':''}><span>${s}</span>${l}</label>`).join('')}</div></fieldset>
 ${preferenceFields()}<details class="body-crosscheck"><summary>키·체중도 함께 확인 <small>선택</small></summary>${bodyInputs()}</details>`:`<div class="notice neutral">${icon('info',18)}<span>브랜드가 공개한 <strong>신체 기준표</strong>에서 후보를 찾아요. 옷의 실측 비교와는 달라요.</span></div>${bodyInputs(true)}${observedClothingFields()}`}
 <div id="form-error" class="form-error" role="alert"></div><button class="primary full" type="submit">비교할 옷 고르기 ${icon('arrow')}</button><p class="form-bottom">${icon('check',13)} 가입 없이 바로 비교할 수 있어요</p></form>`;
}
function referenceSummary(){if(state.mode==='body')return `<span class="summary-icon">${icon('ruler',24)}</span><div><small>아이의 현재 신체 정보</small><strong>키 ${esc(state.height)}cm ${state.weight?`· ${esc(state.weight)}kg`:''}</strong>${state.wearingSize?`<span>입던 옷: ${esc(brand(state.wearingBrand)?.name??'브랜드 미확인')} ${esc(state.wearingSize)}</span>`:''}</div>`;const p=product(state.referenceProduct);return `<span class="summary-icon">${icon('hanger',24)}</span><div><small>비교의 기준이 되는 옷</small><strong>${state.manual?'직접 입력한 실측':state.referenceTypical?esc(brand(state.referenceBrand)?.name)+' · '+esc(KINDS[state.referenceKind].label)+' 중간 치수':esc(brand(p?.brandId)?.name)+' · '+esc(displayName(p?.name))}</strong><span>${state.manual?'평평하게 잰 옷 치수':esc(state.referenceSize)+' 사이즈'} · ${state.fit==='well'?'편안하게 맞아요':state.fit==='small'?'조금 작아졌어요':'여유가 많아요'}</span>${preferenceSummary()}</div>`;}
function secondStep(){const reference=product(state.referenceProduct);const products=data.products.filter(p=>(state.targetBrand==='all'||p.brandId===state.targetBrand)&&p.kind===state.referenceKind&&isComparable(p)&&(p.audience??'child')===(reference?.audience??'child')).filter(p=>p.id!==state.referenceProduct);return `<div class="form-heading"><span class="section-number">02</span><div><h2>${state.mode==='body'?'어떤 브랜드가 궁금하세요?':'다음엔 어떤 옷을 입힐까요?'}</h2><p>${state.mode==='body'?'브랜드별 공식 신체 기준을 함께 볼 수 있어요.':'브랜드 전체를 둘러보거나 상품 하나를 골라보세요.'}</p></div></div><div class="reference-summary">${referenceSummary()}<button data-action="back" aria-label="기준 정보 수정">수정</button></div><form id="target-form"><label class="field-label" for="target-brand">비교할 브랜드</label><select id="target-brand" name="targetBrand"><option value="all">모든 브랜드 비교하기</option>${data.brands.map(b=>`<option value="${b.id}" ${state.mode==='body'&&!b.bodyGuide.rows.length?'disabled':''} ${state.targetBrand===b.id?'selected':''}>${esc(b.name)}${state.mode==='garment'?' · '+products.filter(p=>p.brandId===b.id).length+'개 실측':!b.bodyGuide.rows.length?' · 신체표 미확보':''}</option>`).join('')}</select>${state.mode==='garment'?`<label class="field-label" for="target-product">궁금한 상품 <small>선택</small></label><select id="target-product" name="targetProduct"><option value="all">확보된 모든 상품에서 찾기</option>${products.map(p=>`<option value="${p.id}" ${state.targetProduct===p.id?'selected':''}>${esc(brand(p.brandId).name)} · ${esc(displayName(p.name))}</option>`).join('')}</select><div class="notice neutral">${icon('info',18)}<span>선택한 핏·원단·계절에 맞춰 찾아요. 계절을 고르면 상품명·설명에서 용도를 확인한 옷만 보여드려요.</span></div>`:'<div class="notice neutral">'+icon('info',18)+'<span>범위가 겹치면 여러 후보를 보여드려요. 키와 체중 기준이 다르면 추천을 보류해요. 공통 신체표를 확보하지 못한 브랜드('+data.brands.filter(b=>!b.bodyGuide.rows.length).map(b=>esc(b.name)).join('·')+')는 이 방식에서 제외하며, 상품 실측으로 비교할 수 있어요.</span></div>'}<button class="primary full" type="submit">${state.mode==='garment'?'가까운 사이즈 찾아보기':'브랜드별 가이드 확인하기'} ${icon('spark',19)}</button><button type="button" class="secondary full" data-action="back">${icon('back',16)} 기준 정보 다시 선택</button></form>`;}
function aside(){return `<aside class="compare-aside"><span class="aside-label">A LITTLE GUIDE</span><h3>같은 숫자여도,<br>크기는 다르니까.</h3><div class="mini-comparison"><div>${clothes('#f1c8d7','dots','side-a')}<span>A 브랜드 · 80</span></div><span class="versus">≠</span><div>${clothes('#bfdde7','dots','side-b')}<span>B 브랜드 · 80</span></div></div><p>익숙한 옷의 치수를 기준으로<br>길이와 품의 차이를 살펴보세요.</p><div class="aside-divider"></div><div class="aside-note">${icon('book',19)}<div><strong>출처가 있는 데이터만</strong><span>공식 표를 확인하고, 둘레와 단면을 구분했어요.</span></div></div><button class="text-link" data-action="method">어떻게 비교하나요? ${icon('arrow',16)}</button></aside>`;}
function compareView(){return `${state.step===1?hero():''}<section class="workspace ${state.step===3?'results-workspace':''}" id="workspace">${stepper()}${state.step===3?resultsView():`<div class="workspace-grid"><section class="form-panel">${state.step===1?firstStep():secondStep()}</section>${aside()}</div>`}</section>${state.step===1?`<section class="brand-strip"><div><span class="eyebrow">함께 비교하는 브랜드</span><p>익숙한 브랜드부터, 처음 만나는 브랜드까지.</p></div><div class="brand-wordmarks">${data.brands.map(b=>`<button data-action="brand-detail" data-brand="${b.id}">${esc(b.english)}<small>${esc(b.name)}</small></button>`).join('')}</div><button class="text-link" data-action="view" data-view="database">전체 데이터 보기 ${icon('arrow',16)}</button></section>`:''}`;}
function differencesTable(candidate){return `<div class="table-wrap"><table class="diff-table"><thead><tr><th>비교 부위</th><th>입던 옷</th><th>후보 옷</th><th>차이</th></tr></thead><tbody>${candidate.differences.map(d=>`<tr><th>${d.label}</th><td>${fmt(d.reference)}</td><td>${fmt(d.value)}</td><td><span class="delta ${d.delta>0?'positive':d.delta<0?'negative':'same'}">${d.delta>0?'+':''}${fmt(d.delta)}</span></td></tr>`).join('')}</tbody></table></div><p class="table-caption">단위 cm · +는 더 길거나 넓음 · −는 더 짧거나 좁음</p>`;}
function garmentCard(c,i){const b=brand(c.brandId),p=product(c.productId),keyword=keywordBadge(p,state.season),level=fitLevel(c);return `<article class="result-card"><div class="result-card-top"><span class="badge ${level==='hold'?'amber':i===0&&level==='close'?'purple':''}">${c.userSelected?'직접 선택한 사이즈':level==='hold'?'추천 보류 · 치수 차이가 커요':state.fit==='small'?'조금 더 큰 추천':state.fit==='large'?'조금 더 작은 추천':i===0&&level==='close'?'실측이 가장 가까운 후보':level==='close'?'치수가 가까운 후보':'차이를 확인할 후보'}</span><button class="icon-button" data-action="save" data-index="${i}" aria-label="${esc(b.name+' '+c.size)} 비교 저장">${icon('save',19)}</button></div><div class="product-heading">${productArt(p,'result-'+i)}<div><small>${esc(b.name)}</small><h3>${esc(displayName(p.name))}</h3><span class="size-label">${esc(c.size)}${/^d+$/.test(c.size)?' <small>사이즈</small>':''}</span><span class="keyword-badge ${keyword.key}" title="${esc(keyword.evidence)}">${esc(keyword.label)}</span></div></div><div class="candidate-description">${explainCandidate(c)}</div>${level==='hold'?`<p class="body-check mismatch">${holdReason(c,p)}</p>`:''}${p.measurementCaution?`<p class="body-check partial">${esc(p.measurementCaution)}</p>`:''}${c.bodyCheck?`<p class="body-check ${c.bodyCheck.status}" title="${esc(c.bodyCheck.detail)}">${esc(c.bodyCheck.label)}</p>`:''}${differencesTable(c)}<details class="candidate-details"><summary>인접 사이즈도 보기</summary><div class="adjacent-list">${p.sizes.filter(s=>KINDS[p.kind].required.every(k=>Number.isFinite(s[k]))).map(s=>`<button class="${s.label===c.size?'current':''}" data-action="candidate-size" data-index="${i}" data-size="${esc(s.label)}">${esc(s.label)}</button>`).join('')}</div><p class="field-help">숫자가 커져도 모든 부위가 같은 비율로 커지지는 않아요.</p></details><details class="candidate-details"><summary>공식 치수·소재 안내</summary><p class="field-help">원단: ${esc(p.attributes?.material||fabricLabel(p)||'미확인')}${p.attributes?.origins?.length?' · 제조국: '+esc(p.attributes.origins.join(', ')):''}</p><p class="field-help">${esc(keyword.evidence)}</p><p class="field-help">${p.notes.map(esc).join(" ")}</p></details><div class="result-source"><span>${esc(p.measurementBasis)}</span><a href="${esc(p.source.url)}" target="_blank" rel="noopener noreferrer">공식 상품 ${icon('external',13)}</a></div></article>`;}
function explainCandidate(c){return esc(summarizeDifferences(c));}
function holdReason(c,p){const narrow=c.differences.some(d=>['chestWidth','waistWidth'].includes(d.key)&&d.delta<=-2);return isStretchy(p)&&narrow?'이 상품에서 가장 가까운 사이즈도 품 차이가 커요. 골지·스판처럼 늘어나는 원단은 평평하게 잰 실측이 작게 나와요. 공식 상품의 착용 정보를 함께 확인해 주세요.':'이 상품에서 가장 가까운 사이즈도 치수 차이가 커서 추천하지 않아요. 인접 사이즈의 실측을 직접 확인해 주세요.';}
function brandSummary(results){const rows=summarizeByBrand(results);if(!rows.length)return '';return `<section class="brand-summary" aria-label="브랜드별 결론"><h3>브랜드별로 보면</h3><p class="field-help">상품마다 가장 가까운 사이즈를 찾은 뒤, 브랜드 안에서 가장 많이 나온 호칭을 모았어요.</p><ul>${rows.map(r=>{const b=brand(r.brandId);return `<li><button data-action="summary-brand" data-brand="${r.brandId}"><span class="brand-avatar" style="background:${b.color};color:${b.ink}">${esc(b.name.slice(0,1))}</span><span class="summary-brand-name">${esc(b.name)}</span><strong class="summary-size ${r.level}">${r.size?esc(r.size):'추천 보류'}</strong><span class="summary-note">${r.size?`${r.total}개 상품 중 ${r.count}개${r.level==='check'?' · 2cm 넘는 차이 있음':''}${r.others.length?' · 상품에 따라 '+r.others.map(esc).join('·'):''}${r.held?' · 보류 '+r.held+'개':''}`:`${r.total}개 상품 모두 치수 차이가 커요`}</span>${icon('arrow',14)}</button></li>`;}).join('')}</ul></section>`;}
// 키·체중 기준이 갈릴 때: 두 후보 호칭의 실제 옷 치수(브랜드 상품들의 중간값)를 나란히 보여 준다. 하나를 추천하지 않고 선택을 돕는다.
function typicalFor(brandId,row,kind){for(const label of [row.label,row.nominalLabel,...String(row.label).split(/[()]/)].map(v=>String(v??'').trim()).filter(Boolean)){const t=typicalReference(data,{brand:brandId,kind,size:label});if(t)return {...t,label};}return null;}
function conflictCompare(c){
 const h=c.heightRows?.[0],w=c.weightRows?.[0];if(!h||!w||h===w)return '';
 for(const kind of [...new Set([state.referenceKind,'homewear-set','set','top'])]){
  const a=typicalFor(c.brandId,h,kind),b=typicalFor(c.brandId,w,kind);if(!a||!b)continue;
  const keys=KINDS[kind].fields.filter(k=>k!=='waistWidth'&&Number.isFinite(a.values[k])&&Number.isFinite(b.values[k]));if(!keys.length)continue;
  const delta=k=>Math.round((b.values[k]-a.values[k])*100)/100,widthGap=Number.isFinite(a.values.chestWidth)&&Number.isFinite(b.values.chestWidth)?delta('chestWidth'):null,lengthKeys=keys.filter(k=>k!=='chestWidth'),lengthGap=lengthKeys.length?Math.max(...lengthKeys.map(k=>Math.abs(delta(k)))):null;
  const pick=state.bodyPriority?.[c.brandId],bigger=widthGap!==null&&widthGap<0?h:w,smaller=bigger===h?w:h;
  return `<div class="conflict-help"><p class="field-help"><strong>${esc(KINDS[kind].label)}</strong> 기준 · 이 브랜드 상품 ${a.count}개·${b.count}개의 중간 치수예요.</p><div class="table-wrap"><table class="diff-table"><thead><tr><th>비교 부위</th><th>${esc(h.label)} <small>키 기준</small></th><th>${esc(w.label)} <small>체중 기준</small></th><th>차이</th></tr></thead><tbody>${keys.map(k=>`<tr><th>${ALL_DIMENSIONS[k]}</th><td>${fmt(a.values[k])}</td><td>${fmt(b.values[k])}</td><td><span class="delta ${delta(k)>0?'positive':delta(k)<0?'negative':'same'}">${delta(k)>0?'+':''}${fmt(delta(k))}</span></td></tr>`).join('')}</tbody></table></div><p class="table-caption">단위 cm · 차이는 ${esc(w.label)}에서 ${esc(h.label)}를 뺀 값</p><div class="segmented priority-choice" role="group" aria-label="무엇을 우선할까요"><button type="button" data-action="body-priority" data-brand="${c.brandId}" data-priority="width" aria-pressed="${pick==='width'}" class="${pick==='width'?'selected':''}">품이 편한 쪽</button><button type="button" data-action="body-priority" data-brand="${c.brandId}" data-priority="length" aria-pressed="${pick==='length'}" class="${pick==='length'?'selected':''}">길이가 맞는 쪽</button></div>${pick?`<p class="body-check partial"><strong>${pick==='width'?'품을 우선하면 '+esc(bigger.label):'길이를 우선하면 '+esc(smaller.label)}</strong> · ${pick==='width'?(lengthGap?'소매나 길이가 최대 '+fmt(lengthGap)+'cm 길 수 있어요.':'길이 차이는 확인하지 못했어요.'):(widthGap!==null?'품이 '+fmt(Math.abs(widthGap))+'cm 좁을 수 있어요.':'품 차이는 확인하지 못했어요.')} 꼭맞의 추천이 아니라 선택을 돕는 안내예요.</p>`:''}</div>`;
 }
 return '';
}
function bodyHelp(c){
 if(!c.unavailable&&!c.conflict)return '';
 const near=c.unavailable&&(c.below||c.above)?`<p class="field-help">${c.below?`바로 아래 호칭은 <strong>${esc(c.below.label)}</strong>(키 ${rangeLabel(c.below,'cm')})`:''}${c.below&&c.above?', ':''}${c.above?`바로 위 호칭은 <strong>${esc(c.above.label)}</strong>(키 ${rangeLabel(c.above,'cm')})`:''}예요.</p>`:'';
 const hasGarments=data.products.some(p=>p.brandId===c.brandId&&isComparable(p));
 return `${near}${c.conflict&&!c.observedConflict?conflictCompare(c):''}${hasGarments?`<button type="button" class="secondary full body-to-garment" data-action="body-to-garment" data-brand="${c.brandId}">지금 잘 맞는 옷으로 비교하기 ${icon('arrow',16)}</button>`:''}`;
}
function bodyCard(c){
 const b=brand(c.brandId),blocked=c.unavailable||c.conflict,verified=c.confidence==='both'&&!c.conflict;
 const labels=rows=>(rows??[]).map(r=>esc(r.label)).join(' · ')||'해당 범위 없음';
 const status=c.unavailable?(c.below&&c.above?'호칭 사이 빈 구간':'기준 범위 밖'):c.observedConflict?'입던 사이즈와 충돌':c.conflict?'키·체중 기준 충돌':verified?'키·체중 모두 확인':c.ceilingOnly?'공식 상한 기준 참고':c.weightPointOnly?'체중은 단일 참고값':c.pointOnly?'단일 기준 참고값':c.weightUnchecked?'체중 기준 미공개':!c.weightProvided?'체중 미입력':'기준표 참고';
 return `<article class="body-result"><div class="brand-avatar" style="background:${b.color};color:${b.ink}">${esc(b.name.slice(0,1))}</div><div class="body-result-main"><small>${esc(b.english)}</small><h3>${esc(b.name)}</h3><span class="badge ${verified?'purple':'amber'}">${status}</span>${blocked?`<p>${esc(c.reason)}</p>`:`<p class="body-size-caption">${verified?'공식 범위에 해당하는 호칭':'구매 전 확인할 참고 호칭'}</p><div class="body-size ${verified?'':'reference-size'}">${c.rows.map(r=>`<strong>${esc(r.label)}</strong>`).join('<span>또는</span>')}</div>`}${c.heightRows?`<div class="body-axis-grid"><div><small>키 ${esc(state.height)}cm 기준</small><span>${labels(c.heightRows)}</span></div><div><small>체중 ${state.weight?esc(state.weight)+'kg':'미입력'} 기준</small><span>${!c.weightProvided?'확인 전':c.weightUnchecked?'자료 미공개':labels(c.weightRows)}</span></div></div>`:''}${c.observedUnverified?`<p class="field-help">입던 사이즈 ${esc(c.wearingSize)}와 브랜드 호칭을 직접 환산할 수 없어요. 입던 옷 실측으로 확인해 주세요.</p>`:''}${!blocked?`<div class="body-range">${c.rows.map(r=>`<span>키 ${rangeLabel(r,'cm')} ${r.weightRange?' · '+(r.weightRange[0]==null?r.weightRange[1]+'kg 이하':r.weightRange.join('–')+'kg'):Number.isFinite(r.weightPoint)?' · 기준체중 '+r.weightPoint+'kg':''}</span>`).join('')}</div>`:''}${c.ceilingOnly?'<p class="field-help">공식 표는 키·체중 상한만 공개해요. 참고 호칭은 두 상한을 넘지 않는 가장 작은 값이며 적합 범위를 뜻하지 않아요.</p>':c.weightPointOnly?'<p class="field-help">체중은 단일 참고값에 가까운 호칭이에요. 적합 범위를 뜻하지 않아요.</p>':''}${c.pointOnly?'<p class="field-help">단일 기준값에 가까운 호칭이며 착용 범위를 뜻하지 않아요.</p>':''}${c.observedConflict||c.observedUnverified?'<button class="inline-link" data-action="use-observed">입던 옷 실측으로 다시 비교 →</button>':''}${bodyHelp(c)}</div><a class="icon-button" href="${esc(c.source.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(b.name)} 공식 가이드 열기">${icon('external',18)}</a></article>`;
}

function resultsView(){const results=state.results??[];return `<div class="results-header"><div><span class="eyebrow">YOUR NEXT LITTLE FIT</span><h2>${state.mode==='garment'?'다음 옷, 이렇게 비교해 보세요.':'우리 아이의 브랜드별 사이즈 가이드'}</h2><p>${state.mode==='garment'?(state.fit==='well'?'선택한 조건에서 치수가 가장 가까운 사이즈를 골랐어요.':state.fit==='small'?'입던 옷보다 주요 치수가 큰 후보 중 가까운 사이즈를 골랐어요.':'입던 옷보다 주요 치수가 작은 후보 중 가까운 사이즈를 골랐어요.'):'공식 신체 기준표에 해당하는 호칭을 모았어요.'}</p></div><button class="secondary" data-action="reset">다시 비교하기 ${icon('ruler',17)}</button></div><div class="reference-summary result-reference">${referenceSummary()}<button data-action="edit-reference">수정</button></div>${state.mode==='garment'&&state.fit!=='well'?'<div class="notice neutral">'+icon('spark',19)+'<span>'+fitMessage()+' 품과 길이의 실제 차이를 아래에서 확인해 주세요.</span></div>':''}<div class="results-toolbar"><span>${state.mode==='garment'?results.length+'개 상품 비교 · '+Math.min(results.length,state.resultLimit)+'개 표시':'브랜드 가이드 '+results.length+'개'}</span><button class="text-link" data-action="edit-target">비교 대상 변경 ${icon('arrow',14)}</button></div>${results.length?state.mode==='garment'?`${brandSummary(results)}<div class="results-grid">${results.slice(0,state.resultLimit).map(garmentCard).join('')}</div>${results.length>state.resultLimit?`<button class="secondary results-load-more" data-action="more-results">비교 결과 더 보기 · ${results.length-state.resultLimit}개 남음</button>`:''}`:`<div class="body-results">${results.map(bodyCard).join('')}</div>`:`<div class="empty-state">${icon('book',36)}<h3>이 조건으로 비교할 상품 실측이 없어요.</h3><p>${state.mode==='garment'?'선택한 크기 방향·원단·계절을 모두 확인할 수 있는 상품 실측이 없어요.<br>조건을 바꾸거나 다른 브랜드를 살펴보세요.':'다른 브랜드를 선택하거나 입력한 신체 정보를 확인해 주세요.'}</p><button class="inline-link" data-action="edit-reference">기준 조건 수정</button><button class="primary" data-action="edit-target">비교 대상 바꾸기</button></div>`}<div class="results-footnote">${icon('info',20)}<div><strong>${state.mode==='garment'?'치수가 가깝다는 뜻이지, 착용을 보장하지 않아요.':'신체 기준표는 상품의 실측과 달라요.'}</strong><p>${state.mode==='garment'?'가슴·허리 둘레는 2로 나누어 단면과 비교했어요. 브랜드별 측정 지점, 소재의 신축성, 세탁 후 변화는 반영하지 못해요. 1~2cm 차이는 측정 오차일 수 있어요.':'상품별 제공 사이즈가 다를 수 있어요. 실제 구매 전 해당 상품 실측과 옵션을 확인해 주세요.'}</p><button class="inline-link" data-action="method">비교 기준 자세히 보기</button></div></div>`;}
function databaseView(){return renderCatalog(data,state);}
function rangeLabel(r,unit=''){if(!r.heightRange)return fmt(r.height)+unit;const [min,max]=r.heightRange;return min==null?fmt(max)+unit+' 이하':max==null?fmt(min)+unit+' 이상':min===max?fmt(min)+unit:fmt(min)+'–'+fmt(max)+unit;}
function databaseCards(){return renderCatalogCards(data,state);}
function savedView(){return `<section class="page-intro compact"><span class="eyebrow">MY LITTLE COLLECTION</span><h1>고민했던 사이즈,<br><span>여기에 모아둘게요.</span></h1><p>저장한 비교는 이 브라우저에만 보관돼요.</p></section><section class="saved-content">${saved.length?`<div class="saved-grid">${saved.map((s,i)=>`<article class="saved-card"><div class="saved-card-top"><span class="badge">${esc(s.date)}</span><button class="icon-button" data-action="remove-save" data-index="${i}" aria-label="저장한 비교 삭제">${icon('close',18)}</button></div><small>${esc(s.referenceName)}</small><div class="saved-arrow">${icon('arrow',19)}</div><h3>${esc(s.targetName)}</h3><strong class="saved-size">${esc(s.candidate.size)}</strong><p>${s.candidate.differences.slice(0,3).map(d=>`${d.label} ${d.delta>0?'+':''}${fmt(d.delta)}cm`).join(' · ')}</p><button class="secondary full" data-action="open-save" data-index="${i}">비교 자세히 보기 ${icon('arrow',16)}</button></article>`).join('')}</div>`:`<div class="empty-state saved-empty"><div class="empty-save-art">${icon('save',40)}</div><h2>아직 저장한 비교가 없어요.</h2><p>비교 결과의 북마크를 눌러<br>다음에 다시 보고 싶은 사이즈를 모아보세요.</p><button class="primary" data-action="view" data-view="compare">첫 비교 시작하기 ${icon('arrow',17)}</button></div>`}</section>`;}
function render(){app.innerHTML=header()+`<main id="main-content">${state.view==='compare'?compareView():state.view==='database'?databaseView():savedView()}</main>`+footer()+`<dialog id="info-dialog"><button class="dialog-close icon-button" data-action="close-dialog" aria-label="닫기">${icon('close',22)}</button><div id="dialog-content"></div></dialog>`;}
function scrollToWorkspace(){setTimeout(()=>document.querySelector('#workspace')?.scrollIntoView({behavior:'smooth',block:'start'}),30);}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3000);}
function showDialog(content){document.querySelector('#dialog-content').innerHTML=content;document.querySelector('#info-dialog').showModal();}
function methodDialog(){showDialog(`<span class="eyebrow">HOW WE COMPARE</span><h2>숫자의 근거까지,<br>함께 보여드려요.</h2><div class="method-item"><b>01</b><div><h3>상품 실측과 신체 가이드를 나눠요</h3><p>옷의 길이·단면은 옷끼리만 비교해요. 아이 키·체중은 브랜드의 신체 기준표에만 대입해요.</p></div></div><div class="method-item"><b>02</b><div><h3>같은 단위로 맞춰요</h3><p>공식 둘레는 2로 나눈 값을 단면과 나란히 표시해요. 원본은 데이터 파일에 보존해요. 브랜드별 측정 지점이 완전히 같다고 보장하지 않아요.</p></div></div><div class="method-item"><b>03</b><div><h3>가까운 치수의 후보를 찾아요</h3><p>작아진 옷은 주요 치수가 큰 쪽, 여유가 많은 옷은 작은 쪽에서 차이가 가장 적은 사이즈를 골라요. 편안하게 맞는 옷은 가장 가까운 치수를 찾아요. 하의는 허리와 바지 길이, 나머지 의류는 품과 길이를 비교해요.</p></div></div><div class="method-item"><b>04</b><div><h3>차이가 크면 추천을 보류해요</h3><p>주요 치수 중 하나라도 3.5cm 넘게 차이 나면 가장 가까운 사이즈라도 추천하지 않아요. 2cm 이하는 측정 오차 범위로 보고, 그 사이는 차이를 확인할 후보로 표시해요. 브랜드별 결론은 보류가 아닌 상품에서 가장 많이 나온 호칭이에요.</p></div></div><div class="method-item"><b>05</b><div><h3>소매와 바지 길이가 같은 유형끼리만 비교해요</h3><p>반소매와 긴소매, 반바지와 긴바지는 같은 종류라도 서로 비교하지 않아요. 상품명에 적힌 표현을 먼저 보고, 없으면 실측 비율로 짧은 옷을 가려내요. 판단할 치수가 없는 옷은 구분하지 않아요.</p></div></div><div class="method-item"><b>06</b><div><h3>원단·계절·특징도 근거를 확인해요</h3><p>다른 원단은 주요 소재 종류나 확인된 원단 조직이 다른 상품이에요. 혼용률만 다른 옷은 구분하지 않아요. 계절은 공식 상품명·설명의 계절·보온·통기 표현으로 분류하며, 출시 연도로 추정하지 않아요. 미확인 상품은 해당 조건에서 제외해요. 특징 뱃지도 공식 설명과 제조국을 근거로 표시해요.</p></div></div><div class="notice neutral">${icon('info',19)}<span>소재의 신축성·세탁 후 변화·향후 성장과 날씨는 자동 반영하지 않아요. 상품 판매 여부와 재고도 연동하지 않아요.</span></div><button class="secondary full" data-action="sources">데이터 출처 확인 ${icon('arrow',16)}</button>`);}
function sourcesDialog(){showDialog(`<span class="eyebrow">OPEN & TRACEABLE</span><h2>출처가 분명한<br>작은 데이터베이스.</h2><p class="dialog-lead">공식 브랜드몰과 운영사몰에 공개된 표를 확인했어요.<br>확인일 ${data.checkedAt} · ${data.brands.length}개 브랜드 / ${data.products.length}개 상품</p><div class="sources-list">${data.brands.map(b=>`<div><strong>${esc(b.name)}</strong><a href="${esc(b.bodyGuide.source.url)}" target="_blank" rel="noopener noreferrer">신체 가이드 ${icon('external',13)}</a>${data.products.filter(p=>p.brandId===b.id).slice(0,2).map(p=>`<a href="${esc(p.source.url)}" target="_blank" rel="noopener noreferrer">${esc(p.name)} ${icon('external',13)}</a>`).join('')}</div>`).join('')}</div><div class="notice amber">${icon('info',18)}<span>아가방 영아 체중은 표의 열 수가 맞지 않아 제외했어요. 밍크뮤 3세 이상 신체 가이드는 출처 내부 불일치로 제외했어요. 판매·품질 순위와 무관해요.</span></div><div class="download-buttons"><a class="secondary" href="./data.json" download="kokmat-size-database.json">${icon('download',16)} JSON</a><a class="secondary" href="./measurements.csv" download="kokmat-measurements.csv">${icon('download',16)} 상품 실측 CSV</a></div>`);}
function runComparison(){state.resultLimit=12;if(state.mode==='garment'){const p=product(state.referenceProduct),row=p?.sizes.find(s=>s.label===state.referenceSize);state.reference=state.manual?Object.fromEntries(Object.entries(state.manualValues).filter(([,v])=>v!=='').map(([k,v])=>[k,Number(v)])):state.referenceTypical?{...typicalReference(data,{brand:state.referenceBrand,kind:state.referenceKind,size:state.referenceSize})?.values}:{...row,productId:p?.id};state.reference.kind=state.referenceKind;state.results=garmentCandidates(data,state.reference,{brand:state.targetBrand,product:state.targetProduct,fit:state.fit,season:state.season,differentFabric:state.differentFabric,referenceFabric:state.manual||!fabricProfile(p).fibers.length?state.referenceFabric:'',...bodyInputValues(),limit:Infinity}).sort((x,y)=>(fitLevel(x)==='hold')-(fitLevel(y)==='hold'));}else state.results=bodyCandidates(data,{height:Number(state.height),weight:state.weight===''?null:Number(state.weight),brand:state.targetBrand,wearingBrand:state.wearingBrand,wearingSize:state.wearingSize.trim()});state.step=3;render();scrollToWorkspace();}
app.addEventListener('input',e=>{if(e.target.name?.startsWith('manual-'))state.manualValues[e.target.name.slice(7)]=e.target.value;if(['height','weight','wearingSize'].includes(e.target.name))state[e.target.name]=e.target.value;if(e.target.id==='reference-search'){state.referenceSearch=e.target.value;const b=state.referenceBrand;document.querySelector('#reference-results').innerHTML=pickList(data.products.filter(p=>p.brandId===b&&p.kind===state.referenceKind&&isComparable(p)));}if(e.target.id==='database-search'){state.dbSearch=e.target.value;state.dbPage=1;document.querySelector('#database-cards').innerHTML=databaseCards();}});
app.addEventListener('change',e=>{const {name,value}=e.target;if(name==='referenceKind'){state.referenceSearch='';state.referenceFabric='';state.referenceKind=value;state.referenceProduct='';state.referenceSize='';state.manualValues={};render();}if(name==='catalogKind'||name==='catalogStatus'){state[name==='catalogKind'?'dbKind':'dbStatus']=value;state.dbPage=1;document.querySelector('#database-cards').innerHTML=databaseCards();}if(name==='referenceBrand'){state.referenceSearch='';state.referenceFabric='';state.referenceBrand=value;state.referenceProduct='';state.referenceSize='';render();}if(name==='referenceProduct'){state.referenceFabric='';state.referenceProduct=value;state.referenceSize='';render();}if(name==='referenceSize'){state.referenceSize=value;if(state.referenceTypical)render();}if(name==='wearingBrand')state.wearingBrand=value;if(name==='fit'){state.fit=value;render();}if(name==='differentFabric'){state.differentFabric=e.target.checked;render();}if(name==='referenceFabric')state.referenceFabric=value;if(name==='season'){state.season=value;render();}if(name==='targetBrand'){state.targetBrand=value;state.targetProduct='all';render();}if(name==='targetProduct')state.targetProduct=value;});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='reference-form'){if(!e.target.reportValidity())return;if(state.weight&&!state.height){document.querySelector('#form-error').textContent='체중과 함께 키도 입력해 주세요.';return;}if(state.mode==='garment'&&!state.manual&&(state.referenceTypical?!state.referenceSize:(!state.referenceProduct||!state.referenceSize))){document.querySelector('#form-error').textContent='상품 실측을 선택하거나, 직접 잰 치수를 입력해 주세요.';return;}state.step=2;state.targetBrand='all';state.targetProduct='all';render();scrollToWorkspace();}if(e.target.id==='target-form')runComparison();});
app.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='home'){state.view='compare';state.step=1;render();window.scrollTo({top:0,behavior:'smooth'});}
 if(a==='view'){state.view=el.dataset.view;render();window.scrollTo({top:0,behavior:'smooth'});}
 if(a==='mode'){state.mode=el.dataset.mode;state.step=1;render();}
 if(a==='manual'){state.manual=el.dataset.manual==='true';render();}
 if(a==='back'||a==='edit-reference'){state.step=1;render();scrollToWorkspace();}
 if(a==='edit-target'){state.step=2;render();scrollToWorkspace();}
 if(a==='more-results'){state.resultLimit+=12;render();}if(a==='use-observed'){state.referenceTypical=false;state.referenceSearch='';state.mode='garment';state.step=1;state.manual=false;state.referenceBrand=state.wearingBrand;state.referenceProduct='';state.referenceSize='';render();scrollToWorkspace();}if(a==='reset'){state.step=1;state.results=null;render();scrollToWorkspace();}
 if(a==='summary-brand'){state.targetBrand=el.dataset.brand;state.targetProduct='all';runComparison();}
 if(a==='pick-product'){state.referenceProduct=el.dataset.product;state.referenceSize='';state.referenceFabric='';render();document.querySelector('#reference-size')?.scrollIntoView({block:'center',behavior:'smooth'});}
 if(a==='typical'){state.referenceTypical=el.dataset.on==='true';state.referenceProduct='';state.referenceSize='';state.referenceFabric='';render();}
 if(a==='body-priority'){state.bodyPriority[el.dataset.brand]=el.dataset.priority;const y=window.scrollY;render();window.scrollTo(0,y);}
 if(a==='body-to-garment'){state.mode='garment';state.step=1;state.manual=false;state.referenceTypical=false;state.referenceSearch='';state.referenceBrand=el.dataset.brand;state.referenceProduct='';state.referenceSize='';render();scrollToWorkspace();}
 if(a==='method')methodDialog();
 if(a==='sources')sourcesDialog();
 if(a==='close-dialog')document.querySelector('#info-dialog').close();
 if(a==='brand-detail'){state.view='database';state.dbFilter=el.dataset.brand;state.dbSearch='';render();window.scrollTo({top:0,behavior:'smooth'});}
 if(a==='catalog-page'){state.dbPage=Number(el.dataset.page);document.querySelector('#database-cards').innerHTML=databaseCards();document.querySelector('#database-cards').scrollIntoView({behavior:'smooth',block:'start'});}
 if(a==='db-filter'){state.dbFilter=el.dataset.filter;state.dbPage=1;render();}
 if(a==='clear-search'){state.dbSearch='';state.dbFilter='all';state.dbKind='all';state.dbStatus='all';state.dbPage=1;render();}
 if(a==='use-product'){const p=product(el.dataset.product);state.referenceTypical=false;state.referenceSearch='';state.view='compare';state.step=1;state.mode='garment';state.manual=false;state.referenceBrand=p.brandId;state.referenceKind=p.kind;state.referenceProduct=p.id;state.referenceSize='';state.referenceFabric='';render();scrollToWorkspace();}
 if(a==='candidate-size'){const i=Number(el.dataset.index),old=state.results[i],p=product(old.productId),row=p.sizes.find(s=>s.label===el.dataset.size);state.results[i]={...old,size:row.label,userSelected:true,differences:old.differences.map(d=>({...d,value:row[d.key],delta:Math.round((row[d.key]-d.reference)*100)/100}))};render();toast('선택한 사이즈로 비교표를 바꿨어요.');}
 if(a==='save'){const c=state.results[Number(el.dataset.index)];const p=product(state.referenceProduct);const key=[state.manual?'manual':state.referenceTypical?'typical-'+state.referenceBrand:state.referenceProduct,state.referenceSize,c.productId,c.size,JSON.stringify(state.reference)].join('|');if(saved.some(s=>s.key===key)){toast('이미 저장한 비교예요.');return;}saved.unshift({key,date:new Date().toLocaleDateString('ko-KR'),candidate:c,referenceName:state.manual?'직접 입력한 옷 치수':state.referenceTypical?brand(state.referenceBrand).name+' '+KINDS[state.referenceKind].label+' 중간 치수 '+state.referenceSize:brand(p.brandId).name+' '+displayName(p.name)+' '+state.referenceSize,targetName:brand(c.brandId).name+' '+displayName(c.name)});try{localStorage.setItem('kokmat-comparisons',JSON.stringify(saved));toast('이 브라우저에 비교를 저장했어요.');}catch{saved.shift();toast('브라우저 저장 공간을 사용할 수 없어요.');}render();}
 if(a==='remove-save'){saved.splice(Number(el.dataset.index),1);try{localStorage.setItem('kokmat-comparisons',JSON.stringify(saved));}catch{}render();toast('저장한 비교를 삭제했어요.');}
 if(a==='open-save'){const s=saved[Number(el.dataset.index)];showDialog(`<span class="eyebrow">SAVED COMPARISON</span><h2>${esc(s.targetName)}</h2><p class="dialog-lead">기준: ${esc(s.referenceName)}<br>후보: ${esc(s.candidate.size)} 사이즈</p>${differencesTable(s.candidate)}<p class="field-help">저장 시점의 비교예요. 데이터가 변경될 수 있으니 구매 전 공식 실측을 다시 확인해 주세요.</p><a class="primary full" href="${esc(s.candidate.source.url)}" target="_blank" rel="noopener noreferrer">공식 상품 확인 ${icon('external',16)}</a>`);}
});
try{const response=await fetch('./data.json');if(!response.ok)throw new Error('data');data=await response.json();const catalogResponse=await fetch('./catalog.json');if(!catalogResponse.ok)throw new Error('catalog');const inventory=await catalogResponse.json();data.catalog=inventory.catalog;data.coverage=inventory.coverage;render();}catch{app.innerHTML='<main class="load-error"><h1>데이터를 불러오지 못했어요.</h1><p>인터넷 연결을 확인하고 다시 시도해 주세요.</p><button onclick="location.reload()">다시 불러오기</button></main>';}
